# DEFECT: j dirigido (divide por len(ta)) → no es simétrico
def j(a, b):
    ta, tb = set(a.casefold().split()), set(b.casefold().split())
    if not ta:
        return 0.0
    return len(ta & tb) / len(ta)

a, b = "ana pe xx", "pe ana"
print(j(a, b) == j(b, a))

